operacionais.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/914c9f5d-b8c5-44af-b302-1947b55bd115","category":"H3","reason":"Consiste na investigação estruturada de incidentes e reclamações para verificar conformidade regulatória.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/9153d8b4-f8ac-4a2c-99d2-383f5c129af1","category":"H1","reason":"É uma competência clínica altamente especializada de apoio a procedimentos neurocirúrgicos para epilepsia.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/9156104b-9bcb-4c22-aaa8-02e3e990ebc7","category":"H1","reason":"Refere-se ao domínio técnico de sistemas, transmissão e equipamento de telecomunicações marítimas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/91571a67-f9e1-4c5b-80c5-43f3d14a3747","category":"H3","reason":"Consiste no procedimento técnico estruturado de registar e documentar intervenções de restauro.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/91613477-9276-4f69-8002-4de21c37d583","category":"H3","reason":"Refere-se a procedimentos operacionais específicos de manuseamento, carregamento e armazenamento de coquilhas.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/9161e2c5-3edc-4b85-acc9-b91c78f4872a","category":"S1","reason":"O essencial é colaborar e comunicar com meios de comunicação para promover o desporto e motivar públicos.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/916708d4-9890-4ed1-a46f-3742981aa8ab","category":"H3","reason":"Consiste em técnicas práticas de reparação de treliças e fixação de videiras.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/9168f6e4-6615-4eea-97c3-1fd0123d78b9","category":"H3","reason":"Montagem e assistência em rampa aeroportuária são procedimentos técnicos operacionais de manuseamento de bagagem e equipamentos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/91695ae9-5236-4d68-af03-419dfec43b00","category":"H3","reason":"A prescrição de programas de exercício aplica princípios técnicos estruturados de programação do treino.","certainty":"high"}]$m82_json$::jsonb;
  v_found integer;
begin
  select count(distinct item.uri) into v_found
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification');
  if v_found <> jsonb_array_length(v_input) then
    raise exception 'M82_ESCO_MAPPING_MISMATCH: found %, expected %', v_found, jsonb_array_length(v_input);
  end if;
  if exists (
    select mapping.concept_id
    from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
    join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
    join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
    group by mapping.concept_id having count(distinct item.category)>1
  ) then raise exception 'M82_ESCO_CANONICAL_CLASS_CONFLICT'; end if;
  insert into public.knowledge_competency_classifications
    (concept_id, subgroup_id, version, taxonomy_version, method, provenance)
  select distinct on (concept.id)
    concept.id, subgroup.id,
    coalesce((select max(history.version)+1 from public.knowledge_competency_classifications history
      where history.concept_id=concept.id),1),
    'competency-taxonomy-2.0.0', 'ai_assisted',
    jsonb_build_object('source','ESCO','sourceVersion','1.2.1','sourceURI',item.uri,
      'sourceHash','1b5e5356d4037cdd5c938131b385b9059a1e5f256ca621e8372b6633ec9aea80',
      'classifierVersion','prisma-competency-classification-1.1.0',
      'model','gpt-5.6-terra', 'reason',item.reason,'certainty',item.certainty,
      'agreement','M8.2-1.0.0')
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification')
  join public.competency_subgroups subgroup on subgroup.code=item.category and subgroup.scope='global' and subgroup.status='active'
  where not exists (select 1 from public.knowledge_competency_classifications current_class
    where current_class.concept_id=concept.id and current_class.is_current)
  order by concept.id,item.uri;
end $m82$;
